function stageMarkup(stages) {
  return stages.map((stage, index) => '<span><b>' + String(index + 1).padStart(2, "0") + '</b>' + escapeHtml(stage) + '</span>').join("");
}

function evidenceMarkup(data) {
  const items = Array.isArray(data.evidenceImages) ? data.evidenceImages : [];
  if (items.length) {
    return items.map((item, index) => [
      '<figure class="evidence-page__item"><div class="shot"><img loading="lazy" src="data:', item.mimeType, ';base64,', item.image, '" alt="', escapeHtml(item.label), '"></div>',
      '<figcaption><b>', String(index + 1).padStart(2, "0"), '</b><span>', escapeHtml(item.label), '</span></figcaption></figure>',
    ].join("")).join("");
  }
  return data.viewports.map((viewport, index) => [
    '<figure class="evidence-page__item"><div class="shot empty"><span>', escapeHtml(viewport), '</span></div>',
    '<figcaption><b>', String(index + 1).padStart(2, "0"), '</b><span>', escapeHtml(viewport), '</span></figcaption></figure>',
  ].join("")).join("");
}

function evidencePageMarkup(data, text) {
  const count = data.evidenceImages?.length || data.viewports.length;
  return [
    '<section class="evidence-page" aria-label="', escapeHtml(text.evidence), '">',
    '<div class="evidence-page__frame"><header class="evidence-page__head"><div><small>DSH / SHOWCASE</small><h2>', escapeHtml(text.evidence), '</h2></div>',
    '<span>', String(count).padStart(2, "0"), ' ', escapeHtml(text.captured), '</span></header>',
    '<div class="evidence-page__grid">', evidenceMarkup(data), '</div></div>',
    '<p class="evidence-page__footer mono">', escapeHtml(text.footer), '</p></section>',
  ].join("");
}

function currentRouteMarkup(stages, text) {
  const nodes = stages.map((stage, index) => [
    '<span><b>', String(index + 1).padStart(2, "0"), '</b><em>', escapeHtml(stage), '</em></span>',
  ].join("")).join("");
  return [
    '<section class="current-route" aria-label="', escapeHtml(text.route), '"><header><small>', escapeHtml(text.routeMeta), '</small><b>', escapeHtml(text.route), '</b></header>',
    '<svg class="route-swell" viewBox="0 0 1000 140" preserveAspectRatio="none" aria-hidden="true"><path d="M20 84C144 18 232 120 350 70s206-60 324 0 196 42 306-28"/></svg>',
    '<div class="route-nodes">', nodes, '</div></section>',
  ].join("");
}

function deliveryManifestMarkup(data, text) {
  const emptyItem = '<li class="manifest-empty">' + escapeHtml(text.noRecords) + '</li>';
  const rawGitFiles = (Array.isArray(data.gitFiles) ? data.gitFiles : []).slice(0, 5);
  const untrackedDirectories = rawGitFiles.filter((file) => String(file.path ?? "").endsWith("/") && !(Number(file.additions) || Number(file.deletions)));
  const changedGitFiles = rawGitFiles.filter((file) => !untrackedDirectories.includes(file));
  const gitItems = [
    ...changedGitFiles.map((file) => [
    '<li><span>', escapeHtml(file.path), '</span><b>+', Number(file.additions) || 0, ' / -', Number(file.deletions) || 0, '</b></li>',
    ].join("")),
    ...(untrackedDirectories.length ? [[
      '<li class="manifest-untracked"><span>', escapeHtml(text.manifestUntracked), '</span><b>', String(untrackedDirectories.length).padStart(2, "0"), ' ', escapeHtml(text.manifestFolders), '</b></li>',
    ].join("")] : []),
  ].join("") || emptyItem;
  const receipts = (Array.isArray(data.testReceipts) ? data.testReceipts : []).slice(0, 3).map((receipt) => [
    '<li><span>', escapeHtml(receipt.command), '</span><b>✓ ', escapeHtml(receipt.duration), ' · exit ', Number(receipt.exitCode) || 0, '</b></li>',
  ].join("")).join("") || emptyItem;
  const outputLine = [data.reportPath, data.summaryPath, data.posterPath].filter(Boolean).join(" → ");
  const checked = Math.max(Number(data.gitFileCount) || 0, (data.gitFiles ?? []).length, (data.testReceipts ?? []).length);
  const scope = [text.scopeGit, text.scopeTests, text.scopeScreens, text.scopePrivacy, text.scopeExport].map((item) => '<span>' + escapeHtml(item) + '</span>').join("");
  const outputSteps = [data.reportPath, data.summaryPath, data.posterPath].filter(Boolean).map((path, index) => [
    '<span><i>', escapeHtml([text.manifestReport, text.manifestSummary, text.manifestPoster][index] ?? text.manifestOutput), '</i><strong>', escapeHtml(path), '</strong></span>',
  ].join("")).join("") || '<span class="manifest-output__empty">' + escapeHtml(text.noRecords) + '</span>';
  return [
    '<section class="route-evidence delivery-manifest" aria-label="', escapeHtml(text.manifest), '"><header><div><small>', escapeHtml(text.manifestMeta), '</small><b>', escapeHtml(text.manifest), '</b></div>',
    '<span>', String(checked).padStart(2, "0"), ' ', escapeHtml(text.manifestChecked), '</span></header>',
    '<div class="manifest-grid"><article class="manifest-block"><div class="manifest-block__head"><span>', escapeHtml(text.manifestChanges), '</span><small>', escapeHtml(data.gitRange), '</small></div><ul>', gitItems, '</ul></article>',
    '<article class="manifest-block"><div class="manifest-block__head"><span>', escapeHtml(text.manifestReceipts), '</span><small>', String(data.passedTests || 0), '/', String(data.testCount || 0), ' ', escapeHtml(text.tests), '</small></div><ul>', receipts, '</ul></article></div>',
    '<div class="manifest-scope"><small>', escapeHtml(text.manifestScope), '</small><div>', scope, '</div></div>',
    '<footer class="manifest-output"><div class="manifest-output__meta"><div class="manifest-output__label"><span>', escapeHtml(text.manifestOutput), '</span><small>', escapeHtml(outputLine ? text.ready : text.noRecords), '</small></div><small class="manifest-output__privacy">', Number(data.redactionCount) || 0, ' ', escapeHtml(text.manifestRedactions), ' / ', escapeHtml(text.manifestLocal), '</small></div><div class="manifest-output__path">', outputSteps, '</div></footer></section>',
  ].join("");
}

function whaleSchoolMarkup() {
  const whale = [
    '<path class="whale-body" d="M15 30C23 17 42 10 61 12c16 1 28 8 34 18-5 11-18 18-34 19-19 1-36-6-46-19Z"/>',
    '<path class="whale-tail" d="M91 28c8-8 17-11 25-7-1 6-5 10-12 13 7 1 11 5 12 11-10 2-18-1-25-8Z"/>',
    '<path class="whale-fin" d="M49 41c8 1 14 6 18 12-9 2-16-1-21-7Z"/>',
    '<circle class="whale-eye" cx="35" cy="27" r="1.8"/>',
    '<path class="whale-spout" d="M54 10c-1-5 2-8 6-10m-5 10c4-4 8-4 11-2"/>',
  ].join("");
  return [
    '<div class="whale-school" aria-hidden="true">',
    '<svg class="whale whale-one" viewBox="0 0 122 56">', whale, '</svg>',
    '<svg class="whale whale-two" viewBox="0 0 122 56">', whale, '</svg>',
    '<svg class="whale whale-three" viewBox="0 0 122 56">', whale, '</svg>',
    '</div>',
  ].join("");
}

function bubbleMarkup() {
  return '<div class="bubbles" aria-hidden="true">' + '<i></i>'.repeat(12) + '</div>';
}

function loadingMarkup(text) {
  return [
    '<div class="loader" role="status" aria-label="', escapeHtml(text.loading), '">',
    '<div class="load-flow" aria-hidden="true"><i></i><i></i><i></i></div>',
    '<div class="load-brand"><span class="load-mark">DSH</span><strong>dsh-showcase</strong><small>', escapeHtml(text.loading), '</small></div>',
    '<div class="load-progress" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i></div></div>',
    '<script>setTimeout(function(){var node=document.querySelector(".loader");if(node)node.remove()},900)</script>',
  ].join("");
}

